<style>
.garden-document-editor{--mp-primary:#326650;--mp-primary-dark:#264f3d;--mp-bg:#f6f7f4;--mp-border:#e1e7e1;--mp-muted:#718078;--mp-text:#233e32;--mp-ink:#263c32;color:#263c32;max-width:1440px;margin:0 auto;padding:8px 12px 40px}
.garden-document-editor .mp-page-head{margin:0 0 25px;padding:0;align-items:center}.garden-document-editor .mp-page-head h2{font-size:30px;letter-spacing:-.8px;color:#233e32}.garden-document-editor .mp-page-sub{font-size:14px;color:#718078;margin-top:8px}
.garden-document-editor .garden-editor-eyebrow{color:#74877b;font-size:11px;letter-spacing:1.6px;font-weight:700;margin-bottom:9px;text-transform:uppercase}
.garden-document-editor .content{padding:0;background:transparent}.garden-document-editor .invoice-grid{grid-template-columns:minmax(0,1fr) 330px;gap:24px;max-width:none}
.garden-document-editor .card,.garden-document-editor .mp-card-form{background:#fff;border:1px solid #e1e7e1;border-radius:16px;box-shadow:0 3px 10px #233e3204;margin-bottom:20px;overflow:visible}
.garden-document-editor .card{padding:24px}.garden-document-editor .card-title,.garden-document-editor .mp-card-head h3{font-size:16px;text-transform:none;letter-spacing:-.2px;color:#233e32;font-weight:650}.garden-document-editor .mp-card-head{padding:22px 24px;border-bottom:1px solid #edf0eb;background:transparent}.garden-document-editor .mp-card-body{padding:24px}
.garden-document-editor label,.garden-document-editor .content label{font-size:12px;text-transform:none;letter-spacing:0;color:#65756b;font-weight:550}.garden-document-editor .form-row{gap:18px;margin-bottom:18px}.garden-document-editor .form-row:last-child{margin-bottom:0}.garden-document-editor .form-group{min-width:140px}.garden-document-editor .form-group.wide{flex-basis:280px}
.garden-document-editor input:not([type=checkbox]):not([type=hidden]),.garden-document-editor textarea,.garden-document-editor select{border-radius:9px;border-color:#dfe6df;background:#fff;box-shadow:none;min-height:42px}.garden-document-editor input:focus,.garden-document-editor textarea:focus{border-color:#72a488;outline:2px solid #e3f0e8}.garden-document-editor .select2-container--default .select2-selection--single{min-height:43px;border:1px solid #dfe6df;border-radius:9px}.garden-document-editor .select2-selection__rendered{line-height:40px!important}
.garden-document-editor .garden-document-link{background:#f1f6f0!important;border:1px solid #dfe9df!important;border-radius:14px!important;padding:20px 24px!important;margin:0 0 24px!important}.garden-document-editor .garden-document-link p{font-size:12px!important}
.garden-document-editor .items-table th,.garden-document-editor #quotation_table th{background:#f7f9f5!important;border:0;border-bottom:1px solid #e4eae2;color:#6e7c71!important;padding:16px 12px;font-size:11px;text-transform:none;letter-spacing:0}.garden-document-editor .items-table td,.garden-document-editor #quotation_table td{padding:16px 12px;border-left:0;border-right:0;border-color:#eef1eb}.garden-document-editor .empty-row td{padding:42px 20px;color:#849083}.garden-document-editor .empty-icon{display:none}.garden-document-editor .search-card{margin-bottom:12px}
.garden-document-editor .garden-editor-more{margin-bottom:20px;border:1px solid #e1e7e1;background:#fff;border-radius:14px}.garden-document-editor .garden-editor-more>summary{cursor:pointer;padding:18px 24px;font-size:13px;font-weight:600;color:#536b5c}.garden-document-editor .garden-editor-more .card{border:0;box-shadow:none;margin:0}.garden-document-editor .garden-document-help{font-size:13px;line-height:1.6;color:#718078;margin:10px 0 0}.garden-document-editor .right-column .card:first-child{background:#f5f8f2}.garden-document-editor .actions .btn{min-height:46px}.garden-document-editor .btn-primary,.garden-document-editor .mp-btn-primary{background:#326650;color:#fff;border:0;border-radius:9px}.garden-document-editor .total-row.grand-total{font-size:24px}
.garden-document-editor #quotation-form{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:0 24px;align-items:start}.garden-document-editor #quotation-form>.garden-document-link{grid-column:1/-1}.garden-document-editor #quotation-form>.garden-quote-details{grid-column:1;grid-row:2}.garden-document-editor #quotation-form>.garden-quote-lines{grid-column:1;grid-row:3}.garden-document-editor #quotation-form>.garden-quote-summary{grid-column:2;grid-row:2/span 3;position:sticky;top:90px}.garden-document-editor .garden-quote-summary .r-equal{display:block!important}.garden-document-editor .garden-quote-summary .r-equal>div{width:100%!important;max-width:none!important;flex:none!important}.garden-document-editor .garden-quote-summary .totals-table{width:100%}.garden-document-editor .garden-quote-summary .totals-table th,.garden-document-editor .garden-quote-summary .totals-table td{font-size:13px!important;padding:12px 0}.garden-document-editor .garden-quote-summary .totals-table h4{font-size:16px}.garden-document-editor .garden-quote-summary .mp-form-grid{display:flex;gap:8px}.garden-document-editor .garden-quote-summary .mp-form-grid>*{min-width:0;width:50%}
@media(max-width:1200px){.garden-document-editor .invoice-grid,.garden-document-editor #quotation-form{grid-template-columns:minmax(0,1fr)}.garden-document-editor #quotation-form>.mp-card-form{grid-column:1;grid-row:auto;position:static}.garden-document-editor .right-column{position:static}.garden-document-editor{padding:4px 0 30px}}
.garden-document-editor .hide{display:none!important}</style>
